<script setup lang="ts">defineProps<{page:number;total:number;more:boolean;busy?:boolean}>();defineEmits<{change:[page:number]}>();</script>
<template><footer class="flex flex-wrap items-center justify-between gap-2 border-t border-gray-100 px-4 py-3 text-xs text-gray-500"><span>共 {{total}} 条 · 第 {{page}} 页</span><div class="flex gap-2"><button class="btn-secondary !py-1 text-xs" :disabled="page<=1||busy" @click="$emit('change',page-1)">上一页</button><button class="btn-secondary !py-1 text-xs" :disabled="!more||busy" @click="$emit('change',page+1)">下一页</button></div></footer></template>
